-- Catálogo CURADO: permisos con explicación en español y peso propio del proyecto.
-- protection_level: datos oficiales de AOSP. source: claves de docs/fuentes.md.
-- severity y weight: ponderación propia, apoyada en esas fuentes (ajustable).
-- Se ejecuta DESPUÉS del catálogo automático y lo sobrescribe en estos permisos.
ON CONFLICT (android_name) DO UPDATE SET
  friendly_title = EXCLUDED.friendly_title,
  explanation = EXCLUDED.explanation,
  severity = EXCLUDED.severity,
  weight = EXCLUDED.weight,
  icon = EXCLUDED.icon,
  protection_level = EXCLUDED.protection_level,
  source = EXCLUDED.source,
  curated = true;
